mapper.select:
select distinct VENDOR_ID,VENDOR_CODE,VENDOR_NAME
from ceea_storage_return
where ORG_ID = #{organizationId}
and DEAL_DATE >= #{perStartMonth}
and DEAL_DATE  <   #{perEndMonth}

    and VENDOR_CODE like concat('%', #{vendorCode}, '%')


    and VENDOR_NAME like concat('%', #{vendorName}, '%')
